// NVNformat -> VkFormat (see nvn_fmt_vk.h). Entries follow nvn_fmt_mtl.c entry by entry; differences from Metal:
// Vulkan has RGB10A2 signed formats (A2B10G10R10_S*), the 4/5/6-bit packed formats with both component orders, and
// D24 formats only on some vendors (not AMD), so DEPTH24 stays a 32-bit float depth as on Metal.
#include "nvn_fmt_vk.h"
#include <vulkan/vulkan_core.h>

typedef struct { uint32_t vk; uint8_t kind, noalpha, rb, conv; uint32_t dec; } ent;
#define E(f) {f, 1, 0, 0, 0, 0}
#define X(f) {f, 1, 1, 0, 0, 0}
#define S(f) {f, 2, 0, 0, 0, 0}
#define SX(f) {f, 2, 1, 0, 0, 0}
#define SR(f) {f, 2, 0, 1, 0, 0}
#define SXR(f) {f, 2, 1, 1, 0, 0}
#define RGB(f, d) {f, 2, 1, 0, NVN_VKCONV_RGB_EXPAND, d}   /* stored as 3 components, uploaded as 4 */
#define BC(f, d) {f, 1, 0, 0, NVN_VKCONV_BC, d}
#define BCX(f, d) {f, 1, 1, 0, NVN_VKCONV_BC, d}
#define N {0, 0, 0, 0, 0, 0}

static const ent T[0x9D] = {
    [0x01] = E(VK_FORMAT_R8_UNORM), E(VK_FORMAT_R8_SNORM), E(VK_FORMAT_R8_UINT), E(VK_FORMAT_R8_SINT),
    [0x05] = E(VK_FORMAT_R16_SFLOAT), E(VK_FORMAT_R16_UNORM), E(VK_FORMAT_R16_SNORM), E(VK_FORMAT_R16_UINT), E(VK_FORMAT_R16_SINT),
    [0x0A] = E(VK_FORMAT_R32_SFLOAT), E(VK_FORMAT_R32_UINT), E(VK_FORMAT_R32_SINT),
    [0x0D] = E(VK_FORMAT_R8G8_UNORM), E(VK_FORMAT_R8G8_SNORM), E(VK_FORMAT_R8G8_UINT), E(VK_FORMAT_R8G8_SINT),
    [0x11] = E(VK_FORMAT_R16G16_SFLOAT), E(VK_FORMAT_R16G16_UNORM), E(VK_FORMAT_R16G16_SNORM), E(VK_FORMAT_R16G16_UINT), E(VK_FORMAT_R16G16_SINT),
    [0x16] = E(VK_FORMAT_R32G32_SFLOAT), E(VK_FORMAT_R32G32_UINT), E(VK_FORMAT_R32G32_SINT),
    [0x19] = RGB(VK_FORMAT_R8G8B8A8_UNORM, 3), RGB(VK_FORMAT_R8G8B8A8_SNORM, 3), RGB(VK_FORMAT_R8G8B8A8_UINT, 3), RGB(VK_FORMAT_R8G8B8A8_SINT, 3),
    [0x1D] = RGB(VK_FORMAT_R16G16B16A16_SFLOAT, 6), RGB(VK_FORMAT_R16G16B16A16_UNORM, 6), RGB(VK_FORMAT_R16G16B16A16_SNORM, 6), RGB(VK_FORMAT_R16G16B16A16_UINT, 6), RGB(VK_FORMAT_R16G16B16A16_SINT, 6),
    [0x22] = RGB(VK_FORMAT_R32G32B32A32_SFLOAT, 12), RGB(VK_FORMAT_R32G32B32A32_UINT, 12), RGB(VK_FORMAT_R32G32B32A32_SINT, 12),
    [0x25] = E(VK_FORMAT_R8G8B8A8_UNORM), E(VK_FORMAT_R8G8B8A8_SNORM), E(VK_FORMAT_R8G8B8A8_UINT), E(VK_FORMAT_R8G8B8A8_SINT),
    [0x29] = E(VK_FORMAT_R16G16B16A16_SFLOAT), E(VK_FORMAT_R16G16B16A16_UNORM), E(VK_FORMAT_R16G16B16A16_SNORM), E(VK_FORMAT_R16G16B16A16_UINT), E(VK_FORMAT_R16G16B16A16_SINT),
    [0x2E] = E(VK_FORMAT_R32G32B32A32_SFLOAT), E(VK_FORMAT_R32G32B32A32_UINT), E(VK_FORMAT_R32G32B32A32_SINT),
    [0x31] = E(VK_FORMAT_S8_UINT), E(VK_FORMAT_D16_UNORM),
    [0x33] = {VK_FORMAT_D32_SFLOAT, 2, 0, 0, NVN_VKCONV_D24, 0}, E(VK_FORMAT_D32_SFLOAT),
    [0x35] = {VK_FORMAT_D32_SFLOAT_S8_UINT, 2, 0, 0, NVN_VKCONV_D24, 0}, E(VK_FORMAT_D32_SFLOAT_S8_UINT),
    [0x37] = X(VK_FORMAT_R8G8B8A8_SRGB), E(VK_FORMAT_R8G8B8A8_SRGB),
    // 16-bit packed (Tegra: R in the low bits): A4B4G4R4 / A1B5G5R5 have R in the low bits in Vulkan; RGB565 = R5G6B5 reversed
    [0x39] = S(VK_FORMAT_A4B4G4R4_UNORM_PACK16), SX(VK_FORMAT_A1B5G5R5_UNORM_PACK16), S(VK_FORMAT_A1B5G5R5_UNORM_PACK16), S(VK_FORMAT_B5G6R5_UNORM_PACK16),
    [0x3D] = E(VK_FORMAT_A2B10G10R10_UNORM_PACK32), E(VK_FORMAT_A2B10G10R10_UINT_PACK32), E(VK_FORMAT_B10G11R11_UFLOAT_PACK32), E(VK_FORMAT_E5B9G9R9_UFLOAT_PACK32),
    [0x41] = BCX(VK_FORMAT_BC1_RGB_UNORM_BLOCK, VK_FORMAT_R8G8B8A8_UNORM), BC(VK_FORMAT_BC1_RGBA_UNORM_BLOCK, VK_FORMAT_R8G8B8A8_UNORM),
             BC(VK_FORMAT_BC2_UNORM_BLOCK, VK_FORMAT_R8G8B8A8_UNORM), BC(VK_FORMAT_BC3_UNORM_BLOCK, VK_FORMAT_R8G8B8A8_UNORM),
             BCX(VK_FORMAT_BC1_RGB_SRGB_BLOCK, VK_FORMAT_R8G8B8A8_SRGB), BC(VK_FORMAT_BC1_RGBA_SRGB_BLOCK, VK_FORMAT_R8G8B8A8_SRGB),
             BC(VK_FORMAT_BC2_SRGB_BLOCK, VK_FORMAT_R8G8B8A8_SRGB), BC(VK_FORMAT_BC3_SRGB_BLOCK, VK_FORMAT_R8G8B8A8_SRGB),
    [0x49] = BC(VK_FORMAT_BC4_UNORM_BLOCK, VK_FORMAT_R8_UNORM), BC(VK_FORMAT_BC4_SNORM_BLOCK, VK_FORMAT_R8_SNORM),
             BC(VK_FORMAT_BC5_UNORM_BLOCK, VK_FORMAT_R8G8_UNORM), BC(VK_FORMAT_BC5_SNORM_BLOCK, VK_FORMAT_R8G8_SNORM),
             BC(VK_FORMAT_BC7_UNORM_BLOCK, VK_FORMAT_R8G8B8A8_UNORM), BC(VK_FORMAT_BC7_SRGB_BLOCK, VK_FORMAT_R8G8B8A8_SRGB),
             BC(VK_FORMAT_BC6H_SFLOAT_BLOCK, VK_FORMAT_R16G16B16A16_SFLOAT), BC(VK_FORMAT_BC6H_UFLOAT_BLOCK, VK_FORMAT_R16G16B16A16_SFLOAT),
    // *_UI2F / *_I2F: integer storage read as float: integer formats, the shader converts (as on Metal)
    [0x51] = S(VK_FORMAT_R8_UINT), S(VK_FORMAT_R8_SINT), S(VK_FORMAT_R16_UINT), S(VK_FORMAT_R16_SINT), S(VK_FORMAT_R32_UINT), S(VK_FORMAT_R32_SINT),
    [0x57] = S(VK_FORMAT_R8G8_UINT), S(VK_FORMAT_R8G8_SINT), S(VK_FORMAT_R16G16_UINT), S(VK_FORMAT_R16G16_SINT), S(VK_FORMAT_R32G32_UINT), S(VK_FORMAT_R32G32_SINT),
    [0x5D] = RGB(VK_FORMAT_R8G8B8A8_UINT, 3), RGB(VK_FORMAT_R8G8B8A8_SINT, 3), RGB(VK_FORMAT_R16G16B16A16_UINT, 6), RGB(VK_FORMAT_R16G16B16A16_SINT, 6),
             RGB(VK_FORMAT_R32G32B32A32_UINT, 12), RGB(VK_FORMAT_R32G32B32A32_SINT, 12),
    [0x63] = S(VK_FORMAT_R8G8B8A8_UINT), S(VK_FORMAT_R8G8B8A8_SINT), S(VK_FORMAT_R16G16B16A16_UINT), S(VK_FORMAT_R16G16B16A16_SINT), S(VK_FORMAT_R32G32B32A32_UINT), S(VK_FORMAT_R32G32B32A32_SINT),
    [0x69] = E(VK_FORMAT_A2B10G10R10_SNORM_PACK32), E(VK_FORMAT_A2B10G10R10_SINT_PACK32), S(VK_FORMAT_A2B10G10R10_UINT_PACK32), S(VK_FORMAT_A2B10G10R10_SINT_PACK32),
    [0x6D] = X(VK_FORMAT_R8G8B8A8_UNORM), X(VK_FORMAT_R8G8B8A8_SNORM), X(VK_FORMAT_R8G8B8A8_UINT), X(VK_FORMAT_R8G8B8A8_SINT),
    [0x71] = X(VK_FORMAT_R16G16B16A16_SFLOAT), X(VK_FORMAT_R16G16B16A16_UNORM), X(VK_FORMAT_R16G16B16A16_SNORM), X(VK_FORMAT_R16G16B16A16_UINT), X(VK_FORMAT_R16G16B16A16_SINT),
    [0x76] = X(VK_FORMAT_R32G32B32A32_SFLOAT), X(VK_FORMAT_R32G32B32A32_UINT), X(VK_FORMAT_R32G32B32A32_SINT),
    [0x95] = S(VK_FORMAT_R5G6B5_UNORM_PACK16), SX(VK_FORMAT_A1R5G5B5_UNORM_PACK16), S(VK_FORMAT_A1R5G5B5_UNORM_PACK16), S(VK_FORMAT_R5G5B5A1_UNORM_PACK16),
    [0x99] = X(VK_FORMAT_B8G8R8A8_UNORM), E(VK_FORMAT_B8G8R8A8_UNORM), X(VK_FORMAT_B8G8R8A8_SRGB), E(VK_FORMAT_B8G8R8A8_SRGB),
};

static const uint8_t astc_w[14] = {4, 5, 5, 6, 6, 8, 8, 8, 10, 10, 10, 10, 12, 12}, astc_h[14] = {4, 4, 5, 5, 6, 5, 6, 8, 5, 6, 8, 10, 10, 12};
static const uint32_t astc_unorm[14] = {VK_FORMAT_ASTC_4x4_UNORM_BLOCK, VK_FORMAT_ASTC_5x4_UNORM_BLOCK, VK_FORMAT_ASTC_5x5_UNORM_BLOCK, VK_FORMAT_ASTC_6x5_UNORM_BLOCK,
    VK_FORMAT_ASTC_6x6_UNORM_BLOCK, VK_FORMAT_ASTC_8x5_UNORM_BLOCK, VK_FORMAT_ASTC_8x6_UNORM_BLOCK, VK_FORMAT_ASTC_8x8_UNORM_BLOCK, VK_FORMAT_ASTC_10x5_UNORM_BLOCK,
    VK_FORMAT_ASTC_10x6_UNORM_BLOCK, VK_FORMAT_ASTC_10x8_UNORM_BLOCK, VK_FORMAT_ASTC_10x10_UNORM_BLOCK, VK_FORMAT_ASTC_12x10_UNORM_BLOCK, VK_FORMAT_ASTC_12x12_UNORM_BLOCK};

int nvn_fmt_is_astc(int f, int *bw, int *bh, int *srgb) {
    if (f < 0x79 || f > 0x94) return 0;
    int k = (f - 0x79) % 14;
    if (bw) *bw = astc_w[k]; if (bh) *bh = astc_h[k]; if (srgb) *srgb = f >= 0x87;
    return 1;
}
int nvn_fmt_vk(int f, nvn_vkfmt *o) {
    ent e = {0, 0, 0, 0, 0, 0};
    int srgb, bw, bh;
    if (nvn_fmt_is_astc(f, &bw, &bh, &srgb)) {
        int k = (f - 0x79) % 14;
        e = (ent){astc_unorm[k] + (uint32_t)srgb, 1, 0, 0, NVN_VKCONV_ASTC, srgb ? VK_FORMAT_R8G8B8A8_SRGB : VK_FORMAT_R8G8B8A8_UNORM};   // *_SRGB_BLOCK = *_UNORM_BLOCK + 1
    } else if (f > 0 && f < (int)(sizeof T / sizeof *T)) e = T[f];
    if (o) {
        o->vk = e.kind ? e.vk : 0; o->kind = e.kind; o->conv = e.conv; o->vk_decoded = e.conv == NVN_VKCONV_RGB_EXPAND ? e.vk : e.dec;
        o->swz[0] = e.rb ? NVN_SWZ_B : NVN_SWZ_R; o->swz[1] = NVN_SWZ_G; o->swz[2] = e.rb ? NVN_SWZ_R : NVN_SWZ_B; o->swz[3] = e.noalpha ? NVN_SWZ_ONE : NVN_SWZ_A;
    }
    return e.kind;
}
int nvn_fmt_is_depth(int f) { return f >= 0x31 && f <= 0x36; }
int nvn_fmt_has_stencil(int f) { return f == 0x31 || f == 0x35 || f == 0x36; }

uint32_t nvn_vertex_fmt_vk(int f) {
    switch (f) {
        case 0x01: return VK_FORMAT_R8_UNORM; case 0x02: return VK_FORMAT_R8_SNORM; case 0x03: return VK_FORMAT_R8_UINT; case 0x04: return VK_FORMAT_R8_SINT;
        case 0x05: return VK_FORMAT_R16_SFLOAT; case 0x06: return VK_FORMAT_R16_UNORM; case 0x07: return VK_FORMAT_R16_SNORM; case 0x08: return VK_FORMAT_R16_UINT; case 0x09: return VK_FORMAT_R16_SINT;
        case 0x0A: return VK_FORMAT_R32_SFLOAT; case 0x0B: return VK_FORMAT_R32_UINT; case 0x0C: return VK_FORMAT_R32_SINT;
        case 0x0D: return VK_FORMAT_R8G8_UNORM; case 0x0E: return VK_FORMAT_R8G8_SNORM; case 0x0F: return VK_FORMAT_R8G8_UINT; case 0x10: return VK_FORMAT_R8G8_SINT;
        case 0x11: return VK_FORMAT_R16G16_SFLOAT; case 0x12: return VK_FORMAT_R16G16_UNORM; case 0x13: return VK_FORMAT_R16G16_SNORM; case 0x14: return VK_FORMAT_R16G16_UINT; case 0x15: return VK_FORMAT_R16G16_SINT;
        case 0x16: return VK_FORMAT_R32G32_SFLOAT; case 0x17: return VK_FORMAT_R32G32_UINT; case 0x18: return VK_FORMAT_R32G32_SINT;
        case 0x19: return VK_FORMAT_R8G8B8_UNORM; case 0x1A: return VK_FORMAT_R8G8B8_SNORM; case 0x1B: return VK_FORMAT_R8G8B8_UINT; case 0x1C: return VK_FORMAT_R8G8B8_SINT;
        case 0x1D: return VK_FORMAT_R16G16B16_SFLOAT; case 0x1E: return VK_FORMAT_R16G16B16_UNORM; case 0x1F: return VK_FORMAT_R16G16B16_SNORM; case 0x20: return VK_FORMAT_R16G16B16_UINT;
        case 0x21: return VK_FORMAT_R16G16B16_SINT; case 0x22: return VK_FORMAT_R32G32B32_SFLOAT; case 0x23: return VK_FORMAT_R32G32B32_UINT; case 0x24: return VK_FORMAT_R32G32B32_SINT;
        case 0x25: return VK_FORMAT_R8G8B8A8_UNORM; case 0x26: return VK_FORMAT_R8G8B8A8_SNORM; case 0x27: return VK_FORMAT_R8G8B8A8_UINT; case 0x28: return VK_FORMAT_R8G8B8A8_SINT;
        case 0x29: return VK_FORMAT_R16G16B16A16_SFLOAT; case 0x2A: return VK_FORMAT_R16G16B16A16_UNORM; case 0x2B: return VK_FORMAT_R16G16B16A16_SNORM; case 0x2C: return VK_FORMAT_R16G16B16A16_UINT;
        case 0x2D: return VK_FORMAT_R16G16B16A16_SINT; case 0x2E: return VK_FORMAT_R32G32B32A32_SFLOAT; case 0x2F: return VK_FORMAT_R32G32B32A32_UINT; case 0x30: return VK_FORMAT_R32G32B32A32_SINT;
        case 0x3D: return VK_FORMAT_A2B10G10R10_UNORM_PACK32; case 0x69: return VK_FORMAT_A2B10G10R10_SNORM_PACK32; case 0x3F: return VK_FORMAT_B10G11R11_UFLOAT_PACK32;
        case 0x9A: return VK_FORMAT_B8G8R8A8_UNORM;
        // *_UI2F / *_I2F: unnormalized integers converted to float = USCALED / SSCALED
        case 0x51: return VK_FORMAT_R8_USCALED; case 0x52: return VK_FORMAT_R8_SSCALED; case 0x53: return VK_FORMAT_R16_USCALED; case 0x54: return VK_FORMAT_R16_SSCALED;
        case 0x55: return VK_FORMAT_R32_UINT; case 0x56: return VK_FORMAT_R32_SINT;
        case 0x57: return VK_FORMAT_R8G8_USCALED; case 0x58: return VK_FORMAT_R8G8_SSCALED; case 0x59: return VK_FORMAT_R16G16_USCALED; case 0x5A: return VK_FORMAT_R16G16_SSCALED;
        case 0x5B: return VK_FORMAT_R32G32_UINT; case 0x5C: return VK_FORMAT_R32G32_SINT;
        case 0x5D: return VK_FORMAT_R8G8B8_USCALED; case 0x5E: return VK_FORMAT_R8G8B8_SSCALED; case 0x5F: return VK_FORMAT_R16G16B16_USCALED; case 0x60: return VK_FORMAT_R16G16B16_SSCALED;
        case 0x61: return VK_FORMAT_R32G32B32_UINT; case 0x62: return VK_FORMAT_R32G32B32_SINT;
        case 0x63: return VK_FORMAT_R8G8B8A8_USCALED; case 0x64: return VK_FORMAT_R8G8B8A8_SSCALED; case 0x65: return VK_FORMAT_R16G16B16A16_USCALED; case 0x66: return VK_FORMAT_R16G16B16A16_SSCALED;
        case 0x67: return VK_FORMAT_R32G32B32A32_UINT; case 0x68: return VK_FORMAT_R32G32B32A32_SINT;
    }
    return 0;
}
